import{_ as t,a as o,b as i,c as a,d as n,e as r,f as s}from"./chunks/hromadne_operace.0A3C54YA.js";import{_ as l}from"./chunks/spp_polozky3.BRDJgjmN.js";import{_ as p}from"./chunks/filtrace.B2Bh4beK.js";import{_ as c,o as d,c as h,aa as u}from"./chunks/framework.BAs_AphD.js";const m="/buildary-help-preview/media/cs/performedworks/okno_spp_podzhotovitele.png",g="/buildary-help-preview/media/cs/performedworks/spp_zahlavi3.png",f="/buildary-help-preview/media/cs/performedworks/stavy-zp_podzhotovitel2.png",x=JSON.parse('{"title":"Contractor SPP Window","description":"","frontmatter":{"title":"Contractor SPP Window","wiki":"en:performedworks:subcontractor_application_window"},"headers":[],"relativePath":"en/performedworks/subcontractor_application_window.md","filePath":"en/performedworks/subcontractor_application_window.md","lastUpdated":1794388980000}'),b={name:"en/performedworks/subcontractor_application_window.md"};function w(y,e,v,_,P,k){return d(),h("div",null,[...e[0]||(e[0]=[u('<h1 id="contractor-spp-window" tabindex="-1">Contractor SPP Window <a class="header-anchor" href="#contractor-spp-window" aria-label="Permalink to &quot;Contractor SPP Window&quot;">​</a></h1><p>Performed Works between representatives of the subcontractor and contractor (client) are carried out in the Subcontractor SPP process.</p><p>To work in this window, the user must have the appropriate permissions configured, i.e. the company and role assigned under Project Team Members, as described in the &quot;Setting Permissions&quot; section of the Help.</p><p>The window is divided into several separate sections, as shown in the following image:</p><img src="'+m+'" alt="" width="1200" loading="lazy"><h2 id="window-header" tabindex="-1">Window Header <a class="header-anchor" href="#window-header" aria-label="Permalink to &quot;Window Header&quot;">​</a></h2><img src="'+g+'" alt="" loading="lazy"><p>The window header is used to set and display information that is essential for working in the window. Information about the period, contractor, and subcontractor determines which budget items and work statements will be available in the window.</p><p><strong>Period</strong> – Select one of the available options. Creating a new period is described in a separate section of the Help.</p><p><strong>Contractor</strong> – If you represent the contractor, only the organization to which you are assigned will be available. If you represent a subcontractor, all contractors that appear in the project budget will be available.</p><p><strong>Subcontractor</strong> – If you represent a subcontractor, only the organization to which you are assigned will be available. If you represent the contractor, all subcontractors that appear in the project budget will be available.</p><p><strong>Reports</strong> – Opens a window with a list of Measurement Reports for the Contractor/Subcontractor pair selected in the header. A Measurement Report (MR) is a report documenting the Performed Works between a Contractor/Subcontractor pair for a specific period.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Each MR can have one of the following statuses:</strong></p><ul><li>Draft</li><li>Approval</li><li>Proposal Change</li><li>Closed</li></ul></div><figure class="shot" style="--w:650px;"><img src="'+f+'" alt="" loading="lazy"></figure><p><strong>Change Measurement Report Status: -</strong> The buttons for changing the MR status are displayed under this heading. The available buttons depend on the current status of the Measurement Report. Changes to the MR status are protected by permission groups, as described in the &quot;Setting Permissions&quot; section of the Help.</p><h2 id="summary-panel" tabindex="-1">Summary Panel <a class="header-anchor" href="#summary-panel" aria-label="Permalink to &quot;Summary Panel&quot;">​</a></h2><p>The Summary Panel provides an overview of information for the entire project from the perspective of the selected Contractor/Subcontractor pair.</p><img src="'+t+'" alt="" width="1200" loading="lazy"><p><strong>White section of the panel</strong> – Displays total amounts for all periods.</p><p><strong>Colored section of the panel</strong> – Displays amounts relating to the period currently selected in the window header.</p><img src="'+o+'" alt="" width="100" loading="lazy"><ul><li>the house icon indicates that data for all project items is displayed</li><li>the filter icon indicates that the displayed data is calculated only from items that match the currently selected filter.</li></ul><h2 id="items-and-consumption-in-the-current-period" tabindex="-1">Items and Consumption in the Current Period <a class="header-anchor" href="#items-and-consumption-in-the-current-period" aria-label="Permalink to &quot;Items and Consumption in the Current Period&quot;">​</a></h2><p>If no filter is active, the window always displays the items contained in the project parts selected in the Project Structure panel, for example, the items belonging to the project&#39;s first object.</p><img src="'+l+'" alt="" width="1200" loading="lazy"><p><strong>The item window contains several groups of columns:</strong></p><p><strong>Item</strong> – Columns containing item codes and descriptions. The Type distinguishes between a building object, project part, section, and individual items. The checkbox column is used to select items for Bulk Operations. The item name column contains an &quot;i&quot; icon that opens the item details in a separate window.</p><p><strong>Remaining</strong> – This group of columns contains information about the remaining quantity and price of the item. The remaining value is also represented by an icon showing the percentage.</p><p><strong>Selected Period</strong> – This group of columns is used to enter and approve item consumption for the selected period. The columns displayed in this group are dynamic and depend on the status of the Measurement Report and the user&#39;s permissions. Editable cells are highlighted in yellow. The speech bubble icon allows you to add a note to the item consumption. An orange icon indicates that a note exists. Working with this group is described in detail below.</p><p><strong>Completed</strong> – This group of columns contains information about the completed quantity and price of the item. The data also includes consumption for the Selected Period.</p><p><strong>Budget</strong> – Displays information about the total quantity and price of the items. The unit price of the items is also displayed.</p><p><strong>Item Details</strong> – The window displays descriptive information about the item. It also provides summary information about the consumption status and a detailed breakdown of consumption for individual periods. For each consumption entry, information about who approved it and when is also provided. Notes on consumption are also available if they have been entered.</p><img src="'+i+'" alt="" loading="lazy"><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+a+'" alt="" width="300" loading="lazy"></figure><p>The Project Structure panel makes it easier to navigate the budget. The panel displays building objects, project parts, or budget sections. The structure can contain multiple levels with virtually no limit.</p><p>Each level can be expanded to display the next level.</p><p>The grid then displays only the items belonging to the group selected in the Project Structure panel.</p><p>If you need to display a larger range of items, you can select multiple records in the tree using multiselect (Ctrl+mouse click or Shift+mouse click). A Ctrl+click combination can be replaced with a long mouse press.</p><p>For each record, the panel displays a symbol and the number of unresolved and resolved items for the selected period. This is a very useful navigation aid when working with large projects while entering, approving, and modifying items.</p><figure class="shot" style="--w:300px;"><img src="'+n+'" alt="" width="300" loading="lazy"></figure><figure class="shot" style="--w:300px;"><img src="'+r+'" alt="" width="300" loading="lazy"></figure><p>In the Project Structure, the record tree can be expanded and collapsed in bulk using the control buttons above the panel.</p><p>The Project Structure can also be filtered based on the occurrence of a specified string.</p><p>The &quot;Hide Panel&quot; button can be used to make more space available for displaying the grid contents.</p><h2 id="special-functions-panel" tabindex="-1">Special Functions Panel <a class="header-anchor" href="#special-functions-panel" aria-label="Permalink to &quot;Special Functions Panel&quot;">​</a></h2><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>– opens a list of functions that can be used to change data for multiple items at once. Bulk Operations are always applied to the items selected (checked) in the grid. If you need to select multiple items, you can use the checkbox at a higher level.</p><figure class="shot" style="--w:300px;"><img src="'+s+'" alt="" width="200" loading="lazy"></figure><p><strong>Consumption by Amount</strong> – distributes the specified amount among the selected items. The maximum amount that can be consumed is the sum of the remaining prices of the selected items. If both positive and negative items are selected, there is no unambiguous algorithm for reaching the requested resulting price. In this situation, a positive amount entered is distributed only among positive items, while a negative amount is distributed only among negative items. The user is informed of this procedure by a message displayed directly in the application.</p><p><strong>Consumption by Percentage</strong> – consumes the specified percentage of the total item quantity for each selected item. Enter only the value, not the % symbol.</p><p>If the item quantity calculated from the specified percentage exceeds the remaining quantity of the item, the item is consumed only up to its total quantity. This operation therefore cannot result in overconsumption of an item.</p><p><strong>Change Item Status</strong> – this operation changes the status of the selected items to the selected status value. The option is available only when the Measurement Report is in the &quot;Approval&quot; status.</p><p><strong>Delete Consumption</strong> – this operation deletes all entered data for the selected items and sets them to their default status. The option is available only when the Measurement Report is in the &quot;Approval&quot; status.</p><p>Before performing a Bulk Operation, you can choose whether the item selection should remain after the operation is completed. This can be useful if you want to perform another Bulk Operation on the same set of items.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can easily clear the item selection by double-clicking the header of the checkbox column. The first click selects all displayed items, while the second click clears the selection from all items.</p></div><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>The Filtering menu provides predefined filters divided into three groups, depending on which information is used for filtering. The filter is always applied to all project items, so it also affects which records are displayed in the Project Structure panel. If a particular level of the structure contains no items matching the filter, that level is not displayed in the tree.</p><figure class="shot" style="--w:300px;"><img src="'+p+'" alt="" width="200" loading="lazy"></figure><p><strong>Item Status</strong> – allows you to filter items according to their current status. In addition to individual statuses, you can also select aggregate statuses.</p><ul><li><p><strong>Open</strong> – items with the Draft or In Negotiation status, i.e. items that have not yet been resolved.</p></li><li><p><strong>Closed</strong> – items with the Approved, Change, or Rejected status, i.e. items that are considered resolved.</p></li></ul><p><strong>Consumption in the Selected Period</strong> - allows you to filter items according to whether consumption has been entered for the selected period.</p><ul><li><p><strong>Consumed</strong> – have a non-zero value in the Invoiced Quantity column.</p></li><li><p><strong>Not Consumed</strong> – have no value or a zero value in the Invoiced Quantity column.</p></li></ul><p><strong>Consumption in All Periods</strong> - allows you to filter items according to whether consumption has been entered for at least one period.</p><ul><li><p><strong>Consumed</strong> – have a non-zero value in the Invoiced Quantity column for at least one period.</p></li><li><p><strong>Not Consumed</strong> – have no value or a zero value in the Invoiced Quantity column for all periods.</p></li><li><p><strong>Fully Consumed</strong> – have zero remaining quantity.</p></li><li><p><strong>More Than</strong> – items for which more than the specified percentage of the quantity remains to be consumed.</p></li><li><p><strong>Less Than</strong> – items for which less than the specified percentage of the quantity remains to be consumed.</p></li></ul><h3 id="search-by-name-or-code" tabindex="-1">Search by Name or Code <a class="header-anchor" href="#search-by-name-or-code" aria-label="Permalink to &quot;Search by Name or Code&quot;">​</a></h3><p>This function filters the displayed items to show only those containing the specified string. The Code and Description fields are searched.</p><h3 id="printing-and-exports" tabindex="-1">Printing and Exports <a class="header-anchor" href="#printing-and-exports" aria-label="Permalink to &quot;Printing and Exports&quot;">​</a></h3><p>The options for exporting to Excel and PDF are described in the separate SPP Outputs section.</p>',69)])])}const I=c(b,[["render",w]]);export{x as __pageData,I as default};
